    ["From {EventStartDate} - {EventEndDate} participate in the Brewfest Chowdown competition near Ironforge or Orgrimmar."] = "З {EventStartDate} до {EventEndDate} візьми участь у змаганні з наїдання на Хмільному святі поблизу Стальгорна чи Оґриммара.",
    ["From {EventStartDate} - {EventEndDate} participate in the Korrak's Revenge battleground."] = "З {EventStartDate} до {EventEndDate} візьми участь на полі бою «Помста Коррака».",
    ["From {EventStartDate} - {EventEndDate} place 12 Intricately-Painted Eggs or 1 Magnificently-Painted Egg."] = "З {EventStartDate} до {EventEndDate} розклади 12 Вигадливо Розписаних Яєць або 1 Чудово Розписане Яйце.",
    ["From {EventStartDate} - {EventEndDate} present a Lovely Charm Bracelet to one of your faction leaders."] = "З {EventStartDate} до {EventEndDate} подаруй Чарівний Браслет з Підвісками одному з лідерів своєї фракції.",
    ["From {EventStartDate} - {EventEndDate} purchase a contender's outfit from Chapman and defeat another player who is also in a contender's outfit."] = "З {EventStartDate} до {EventEndDate} придбай вбрання суперника в Чапмена і здолай іншого гравця, що також у вбранні суперника.",
    ["From {EventStartDate} - {EventEndDate} purchase the Drake Racer's Helmet from Maztha in Valdrakken."] = "З {EventStartDate} по {EventEndDate} придбайте Шолом Драконячого Гонщика в Мазти у Валдраккені.",
    ["From {EventStartDate} - {EventEndDate} reach 250 stacks of Relieving Frustration by attacking dummies during the quest \"The Gift of Relief\"."] = "З {EventStartDate} до {EventEndDate} досягни 250 стопок ефекту «Відведення Роздратування», атакуючи манекени під час квесту «Дарунок Полегшення».",
    ["From {EventStartDate} - {EventEndDate} ride a balloon around the festival grounds in Tanaris."] = "З {EventStartDate} до {EventEndDate} прокатайся на повітряній кулі над святковим майданчиком у Танарісі.",
    ["From {EventStartDate} - {EventEndDate} ring the Displaced Scarab Gong."] = "З {EventStartDate} до {EventEndDate} удар у Зміщений Гонг Скарабея.",
    ["From {EventStartDate} - {EventEndDate} share a Romantic Picnic Basket at each of the locations offered by the Scenic Getaway Portal."] = "З {EventStartDate} до {EventEndDate} розділи Романтичний Кошик для Пікніка в кожному з місць, які пропонує Портал до Мальовничих Куточків.",
    ["From {EventStartDate} - {EventEndDate} shoot each of the following player races with Turkey Shooters."] = "З {EventStartDate} до {EventEndDate} обстріляй кожну з наведених рас гравців з Індичих Стрільниць.",
    ["From {EventStartDate} - {EventEndDate} slide around the ice rink at the festival grounds in Tanaris."] = "З {EventStartDate} до {EventEndDate} катайся ковзанкою на святковому майданчику в Танарісі.",
    ["From {EventStartDate} - {EventEndDate} speak to Dread Captain DeMeza in Booty Bay and become a member of her crew."] = "З {EventStartDate} по {EventEndDate} поговоріть зі Страхокапітаншею ДеМезою в Бухті Здобичі та станьте членом її команди.",
    ["From {EventStartDate} - {EventEndDate} speak to Dread Captain DeMeza in Booty Bay and complete the quest \"You're Gonna Need A Bigger Boat.\""] = "З {EventStartDate} по {EventEndDate} поговоріть зі Страхокапітаншею ДеМезою в Бухті Здобичі та виконайте квест «Тобі знадобиться більший човен».",
    ["From {EventStartDate} - {EventEndDate} speak to Dread Captain DeMeza in Booty Bay to gain Petey, then defeat Harlan Sweete with Petey on your shoulder."] = "З {EventStartDate} по {EventEndDate} поговоріть зі Страхокапітаншею ДеМезою в Бухті Здобичі, щоб отримати Пітея, а потім здолайте Гарлана Світа з Пітеєм на плечі.",
    ["From {EventStartDate} - {EventEndDate} speak to Javnir Nashak, outside Orgrimmar, or Wagner Hammerstrike, outside Ironforge, and complete the quest \"Honoring a Hero.\""] = "З {EventStartDate} по {EventEndDate} поговоріть з Явніром Нашаком біля Оґриммара чи Вагнером Молотобоєм біля Сталеварки та виконайте квест «Вшанування героя».",
    ["From {EventStartDate} - {EventEndDate} speak to Myrael Lunarbloom in Moonglade to begin the quest."] = "З {EventStartDate} до {EventEndDate} поговори з Мірель Лунарблум на Місячній Галявині, щоб розпочати квест.",
    ["From {EventStartDate} - {EventEndDate} speak to Zinnia Brooks in Goldshire or Sylnaria Fareflame in Razor Hill to being this storyline."] = "З {EventStartDate} до {EventEndDate} поговори з Зіннією Брукс у Золотолужжі або Сильнарією Фарфлейм у Лезогір'ї, щоб розпочати цю сюжетну лінію.",
    ["From {EventStartDate} - {EventEndDate} speak to a Bronze Timekeeper Assistant on Kalimdor for directions to a course location."] = "З {EventStartDate} по {EventEndDate} поговоріть з помічником бронзового хранителя часу в Калімдорі, щоб дізнатися дорогу до місця траси.",
    ["From {EventStartDate} - {EventEndDate} speak to a Bronze Timekeeper in Northrend."] = "З {EventStartDate} до {EventEndDate} поговори з Бронзовим Хранителем Часу в Нортренді.",
    ["From {EventStartDate} - {EventEndDate} speak to a Bronze Timekeeper in the Eastern Kingdoms."] = "З {EventStartDate} до {EventEndDate} поговори з Бронзовим Хранителем Часу в Східних Королівствах.",
    ["From {EventStartDate} - {EventEndDate} speak to a Bronze Timekeeper on Kalimdor."] = "З {EventStartDate} по {EventEndDate} поговоріть з бронзовим хранителем часу в Калімдорі.",
    ["From {EventStartDate} - {EventEndDate} speak to a Bronze Timekeeper on Outland."] = "З {EventStartDate} до {EventEndDate} поговори з Бронзовим Хранителем Часу в Аутленді.",
